// Writes the compiled TipJar / TipToken ABIs to the frontend as typed
// `as const` arrays so wagmi/viem can infer function names and arguments.
// Run after `npx hardhat compile`.
import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";

const root = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const out = path.resolve(root, "../frontend/src/contracts/abis.ts");

const contracts = [
  ["tipJarAbi", "TipJar"],
  ["tipTokenAbi", "TipToken"],
];

let source =
  "// Generated by contracts/scripts/export-abis.mjs. Do not edit by hand.\n";

for (const [exportName, contractName] of contracts) {
  const artifactPath = path.join(
    root,
    "artifacts/contracts",
    `${contractName}.sol`,
    `${contractName}.json`,
  );
  const { abi } = JSON.parse(await readFile(artifactPath, "utf8"));
  source += `\nexport const ${exportName} = ${JSON.stringify(abi, null, 2)} as const;\n`;
}

await writeFile(out, source);
console.log(`Wrote ${path.relative(process.cwd(), out)}`);
